using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.ConceptDynamics.Coding.ResponseRealization;

internal sealed class FullOutResponseIdentificationDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/ConceptDynamics/Coding/ResponseRealization/FullOutResponseIdentification.";

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Repeated full outgoing splits identify with the original response graph and its unchanged finite edge numbering on every history.",
        H("Identify the full outgoing input with the numbered response"),
        Blocks(
            Paragraph(Text("F is any TwoSidedFiniteInduction.Presentation, with its actual graph, finite carriers, essentiality and discrete edge topology. pair is a TablePair F.graph F.graph a b c d for arbitrary natural a,b,c,d. Write q=a+b+1. RepeatedFullOutSplit.stage F q is the actual q-fold full outgoing split with partition id. Its previously constructed identification has vertices the legal q-words and edges the legal (q+1)-words. No graph equivalence or desired history equality is an input.")),
            Paragraph(Text("wordResponse retains the full original legal word and attaches the forced pair.f response to its prefix. Composing that finite equivalence with the q-stage identification gives responseIdentification, with both endpoint equations. response_coordinate uses flatten_window on the actual repeated lift. The private numbering then uses the existing vertexNumber and the inverse of the existing edgeEquiv. numberedIdentification preserves every original parallel-edge number; it defines no replacement matrix or enumerator.")),
            Paragraph(Text("The endpoint-preserving numberedIdentification includes all parallel-edge identities and zero fibers. Restrict its bijection to any endpoint subtype; vertex injectivity proves the inverse endpoint equations. Fintype.card_congr then gives equal endpoint cardinalities, and card_eq_zero_iff identifies emptiness. This is a local consequence of the retained full bijection, including empty carriers.")),
            Paragraph(Text("uncentredRepeatedLift is defined first by the actual repeated lifts followed by the constructed numbered graph homeomorphism. Its decoded coordinates give exactly the future block [t,t+a+b+1]. Comparing with CentredResponseCorrection.uncentred_coordinate yields agrees_existing_uncentred. Composing with the literal -a correction gives numberedLift_eq_repeated_negative and then numberedLift_eq_tower_negative via tower_apply.")),
            Paragraph(Text("OriginalPositiveWordAssembly.positive_word explicitly uses numberedIdentification and numberedLift_eq_tower_negative with F=ResponseTwoSidedConsumer.original G hG. This is an already-written source bridge from the actual input tower to the response-output word, not a missing identification assumption. The source does not itself establish the original-h character, the 2/7 orbit counts, literal Fix(T^6), the same chi obstruction at every 0<n<6, or proof/type axiom closure.")),
            Describe.Remark(DescribeId.Create("response-realization-full-out-response-identification-response-identification"), DeclarationHandle.Create(Prefix + "responseIdentification"), H("responseIdentification"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Constructs the finite vertex and edge relabeling from the actual q-stage full-out graph to the response graph. The private wordResponse inverse retains the original legal word. The retained numberedIdentification and response_coordinate consume this full relabeling.")))),
            Describe.Lean(DescribeId.Create("response-realization-full-out-response-identification-response-coordinate"), DeclarationHandle.Create(Prefix + "response_coordinate"), H("response_coordinate"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every Hist F and integer t, the relabeled repeated lift has exactly the full future response edge. It uses the imported flatten_window identity and is consumed by numbered_coordinate."))), DescribeRole.Theorem),
            Describe.Remark(DescribeId.Create("response-realization-full-out-response-identification-numbered-identification"), DeclarationHandle.Create(Prefix + "numberedIdentification"), H("numberedIdentification"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Composes the constructed response identification with the existing literal vertex and edge numbering, proving source and target preservation. The original positive-word assembly uses this actual finite Relabel as a word leaf.")))),
            
            
            
            Describe.Remark(DescribeId.Create("response-realization-full-out-response-identification-uncentred-repeated-lift"), DeclarationHandle.Create(Prefix + "uncentredRepeatedLift"), H("uncentredRepeatedLift"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The homeomorphism is the actual repeated full-out lift followed by numberedIdentification.homeomorph. It is not defined by the older U. It feeds numbered_coordinate, agrees_existing_uncentred and the negative-centring handoff.")))),
            Describe.Lean(DescribeId.Create("response-realization-full-out-response-identification-numbered-coordinate"), DeclarationHandle.Create(Prefix + "numbered_coordinate"), H("numbered_coordinate"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Existing numbered decoding cancels exactly, after which response_coordinate supplies the full future word. The equality is consumed by agrees_existing_uncentred."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("response-realization-full-out-response-identification-agrees-existing-uncentred"), DeclarationHandle.Create(Prefix + "agrees_existing_uncentred"), H("agrees_existing_uncentred"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Compares every integer coordinate after the injective existing edgeEquiv, using the two full-word coordinate formulas. It is used by numberedLift_eq_repeated_negative."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("response-realization-full-out-response-identification-numbered-lift-eq-repeated-negative"), DeclarationHandle.Create(Prefix + "numberedLift_eq_repeated_negative"), H("numberedLift_eq_repeated_negative"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Replaces the older U by the independently constructed repeated lift and applies the literal negative centring equation. The local tower-form handoff consumes it."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("response-realization-full-out-response-identification-numbered-lift-eq-tower-negative"), DeclarationHandle.Create(Prefix + "numberedLift_eq_tower_negative"), H("numberedLift_eq_tower_negative"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Uses the imported tower_apply equation to express the same -a identity through the actual Tower evaluator. OriginalPositiveWordAssembly.positive_word explicitly consumes this statement for its original-domain word."))), DescribeRole.Theorem))));
}
